namespace WorkspaceAPIs.Enums;

/// <summary>
/// Defines the type/category of a message within a conversation.
/// </summary>
public enum ConversationMessageSenderEnum
{
    /// <summary>
    /// Message sent by an end user.
    /// </summary>
    User,

    /// <summary>
    /// Message generated by the system or AI assistant.
    /// </summary>
    Assistant,

    /// <summary>
    /// Message generated by the system.
    /// </summary>
    System,

    /// <summary>
    /// Message returned by an external tool invoked by the assistant.
    /// </summary>
    Tool,
}